/* Generated by scripts/build-fallback.php — edit resources/js/laundry-receive.js instead. */
/*
|------------------------------------------------------------------------------
| Received House Keeping
|------------------------------------------------------------------------------
| Rebuilds the grid when a vendor is picked, keeps "Left with vendor" moving as
| the counts are typed, and stops a line adding up to more than the vendor is
| actually holding.
|
| The same limit is enforced again on the server before anything is saved (see
| App\Http\Controllers\HkReceivedController::cleanLines), so this file only
| saves the clerk a round trip.
*/

(function () {
    'use strict';

    var boot = window.LAUNDRY_RECEIVE || {};

    var form = document.querySelector('[data-receive]');
    var body = document.querySelector('[data-receive-rows]');
    var vendor = document.querySelector('[data-receive-vendor]');

    if (!form || !body) return;

    var rows = function () {
        return Array.prototype.slice.call(body.querySelectorAll('tr.nv-issue-row'));
    };

    var cell = function (row, name) {
        return row.querySelector('[data-cell="' + name + '"]');
    };

    var num = function (el) {
        var v = parseFloat(el && el.value);

        return isFinite(v) && v > 0 ? v : 0;
    };

    var trim = function (n) {
        return String(Math.round(n * 100) / 100);
    };

    /* ── One line ───────────────────────────────────────────────────────── */

    function syncRow(row) {
        var pending = num(cell(row, 'pending'));
        var counted = num(cell(row, 'received_qty')) + num(cell(row, 'damaged_qty')) + num(cell(row, 'missing_qty'));

        var left = cell(row, 'left');
        var over = counted > pending + 0.0001;

        if (left) left.value = trim(Math.max(0, pending - counted));

        // Say it on the line rather than after a failed save.
        row.classList.toggle('is-over', over);

        ['received_qty', 'damaged_qty', 'missing_qty'].forEach(function (name) {
            var field = cell(row, name);

            if (field) field.classList.toggle('is-invalid', over);
        });

        return over;
    }

    function syncTotals() {
        ['pending', 'received_qty', 'damaged_qty', 'missing_qty', 'left'].forEach(function (name) {
            var box = document.querySelector('[data-rtotal="' + name + '"]');

            if (!box) return;

            box.textContent = trim(rows().reduce(function (sum, row) {
                return sum + num(cell(row, name));
            }, 0));
        });
    }

    function bind(row) {
        ['received_qty', 'damaged_qty', 'missing_qty'].forEach(function (name) {
            var field = cell(row, name);

            if (field) {
                field.addEventListener('input', function () {
                    syncRow(row);
                    syncTotals();
                });
            }
        });
    }

    /* ── The grid is the vendor's outstanding list ──────────────────────── */

    function draw(lines) {
        body.innerHTML = '';

        if (!lines.length) {
            var empty = document.createElement('tr');

            empty.innerHTML = '<td colspan="7" class="nv-muted" style="padding:22px;text-align:center">'
                + 'This vendor is not holding anything right now.</td>';
            body.appendChild(empty);
            syncTotals();

            return;
        }

        lines.forEach(function (line, i) {
            var row = document.createElement('tr');

            row.className = 'nv-issue-row';
            row.innerHTML =
                '<td><strong></strong> <span class="nv-sub"></span>'
                + '<input type="hidden" data-cell="hk_item_id" name="lines[' + i + '][hk_item_id]" /></td>'
                + '<td class="is-num"><input type="text" class="nv-input is-readonly" data-cell="pending" readonly tabindex="-1" /></td>'
                + '<td class="is-num"><input type="number" class="nv-input" data-cell="received_qty" name="lines[' + i + '][received_qty]" value="0" min="0" step="1" /></td>'
                + '<td class="is-num"><input type="number" class="nv-input" data-cell="damaged_qty" name="lines[' + i + '][damaged_qty]" value="0" min="0" step="1" /></td>'
                + '<td class="is-num"><input type="number" class="nv-input" data-cell="missing_qty" name="lines[' + i + '][missing_qty]" value="0" min="0" step="1" /></td>'
                + '<td class="is-num"><input type="text" class="nv-input is-readonly" data-cell="left" readonly tabindex="-1" /></td>'
                + '<td><input type="text" class="nv-input" name="lines[' + i + '][remark]" placeholder="Optional" /></td>';

            // Set through the DOM, never through innerHTML: an item named by a
            // person is not markup.
            row.querySelector('strong').textContent = line.name;
            row.querySelector('.nv-sub').textContent = line.unit || '';
            cell(row, 'hk_item_id').value = line.hk_item_id;
            cell(row, 'pending').value = trim(line.pending);
            cell(row, 'left').value = trim(line.pending);

            ['received_qty', 'damaged_qty', 'missing_qty'].forEach(function (name) {
                cell(row, name).max = line.pending;
            });

            body.appendChild(row);
            bind(row);
        });

        syncTotals();
    }

    function load() {
        var id = vendor && vendor.value;

        if (!id || !boot.pendingUrl) {
            draw([]);

            return;
        }

        fetch(boot.pendingUrl + '?vendor=' + encodeURIComponent(id), {
            headers: { 'X-Requested-With': 'XMLHttpRequest' },
        })
            .then(function (response) { return response.ok ? response.json() : { lines: [] }; })
            .then(function (data) { draw(data.lines || []); })
            .catch(function () { draw([]); });
    }

    if (vendor) vendor.addEventListener('change', load);

    form.addEventListener('submit', function (event) {
        var bad = rows().filter(syncRow);

        if (bad.length) {
            event.preventDefault();
            alert('One line adds up to more than the vendor is holding. Check the highlighted row.');
        }
    });

    /* The server already rendered the picked vendor's rows, so only bind them
       — redrawing here would throw away anything typed before a failed save. */
    rows().forEach(function (row) { bind(row); syncRow(row); });
    syncTotals();
})();
